const assert=require('node:assert/strict'),crypto=require('node:crypto'),{execFileSync}=require('node:child_process'),puppeteer=require('puppeteer-core');
const which=process.argv[2];if(!['beta','main'].includes(which))throw Error('beta or main required');const filename=which==='beta'?'credentials.json':'main-credentials.json';const c=JSON.parse(execFileSync('ssh',['r730','sudo -n cat /mnt/data10tb/codi-public-830-check-20261104/private/'+filename],{encoding:'utf8'}));const base=which==='beta'?'https://beta.ksu.codes/':'https://ksu.codes/',user=which==='beta'?c.a:c.user,file='fresh-list-'+crypto.randomBytes(6).toString('hex')+'.txt',content='Ordinary Files fresh session';
async function login(p){await p.goto(base,{waitUntil:'domcontentloaded',timeout:45000});await p.waitForSelector('.login-gate',{timeout:45000});await p.type('[aria-label=Username]',user);await p.type('[aria-label=Password]',c.password);await p.click('.login-form button[type=submit]');await p.waitForFunction(()=>window.desktopLab?.session?.kind==='registered',{timeout:45000})}
(async()=>{const b=await puppeteer.connect({browserURL:'http://127.0.0.1:19286'}),x=await b.createBrowserContext(),p=await x.newPage();let created=false,y;try{await login(p);await p.evaluate(async({f,t})=>{let m=(await mirrorFileContext()).files;await m.write('/'+f,new Blob([t]));await m.sync()},{f:file,t:content});created=true;y=await b.createBrowserContext();let q=await y.newPage();await q.setViewport({width:1366,height:900});await login(q);await q.evaluate(()=>surfaces.get('Desktop').launch('files'));await q.waitForSelector('.codi-chonky',{timeout:45000});await q.waitForFunction(()=>document.querySelector('.files-content')?.innerText.includes('Files checked with the server.'),{timeout:45000});let found=false;for(let i=0;i<45&&!found;i++){found=!!await q.$(`[data-chonky-file-id="/${file}"]`);if(!found){await q.evaluate(()=>{for(const e of document.querySelectorAll('.codi-chonky *'))if(e.clientHeight>30&&e.scrollHeight>e.clientHeight+10)e.scrollTop=e.scrollHeight});await new Promise(r=>setTimeout(r,1000))}}assert.ok(found,'fresh ordinary Files view did not list synced file');await q.click(`[data-chonky-file-id="/${file}"]`);await q.evaluate(()=>{let x=[...document.querySelectorAll('.codi-chonky button')].find(e=>e.textContent.trim()==='Open in Text');if(!x||x.disabled)throw Error('Open in Text unavailable');x.click()});await q.waitForFunction(v=>document.querySelector('.codi-text-editor .cm-content')?.innerText===v,{timeout:45000},content);console.log(JSON.stringify({site:which,status:'PASS',file,scope:'fresh login → Files → Text; no helper sync in fresh context'}));}finally{if(created){try{let result=await p.evaluate(async({f,t})=>{let m=(await mirrorFileContext()).files,r=await m.read('/'+f);if(new TextDecoder().decode(r.data)!==t)throw Error('Changed; retained');await m.remove('/'+f,r.version);await m.sync();try{await(await serverFileContext()).files.version(f);return 'present'}catch(e){return e.status}},{f:file,t:content});console.log(JSON.stringify({site:which,file,cleanup:result}));if(result!==404)process.exitCode=1}catch(e){console.error('CLEANUP UNCERTAIN',which,file,e.message);process.exitCode=1}}if(y)await y.close();await x.close();b.disconnect()}})().catch(e=>{console.error('Fresh Files check failed:',e.stack);process.exitCode=1});
